SELECT
    ,
    ,
    p.purchase_no AS purchaseNo,
    rf.refund_no AS refundNo,
    sp.supplier_name AS supplierName,
    w.warehouse_name AS warehouseName,
    w.status AS warehouseStatus,
    eu.nickname AS userName


    pi.is_deleted = 0


        AND (pi.receipt_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR pi.remark LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.purchase_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR rf.refund_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR sp.supplier_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR w.warehouse_name LIKE CONCAT('%', #{q.keyword}, '%'))


        AND pi.purchase_id = #{q.purchaseId}


        AND pi.refund_id = #{q.refundId}


        AND pi.supplier_id = #{q.supplierId}


        AND pi.warehouse_id = #{q.warehouseId}


        AND pi.status = #{q.status}


        AND pi.user_id = #{q.userId}


        AND pi.create_time >= #{q.beginTime}


        AND pi.create_time <= #{q.endTime}



ORDER BY pi.id DESC
